 text("J A R V I S",32).setTypeface(null,Typeface.BOLD);text("Джарвис · русский / English",15);status=text("Подготовка локального распознавания…",16);vpnState=text("VPN: "+(Actions.vpnActive(this)?"подключён":"отключён"),13);
