 button("Включить ожидание «Джарвис / Jarvis»",()->start("START"));button("Сказать команду сейчас",()->start("LISTEN"));button("Выключить микрофон и ассистента",()->{getSharedPreferences("service",0).edit().putBoolean("enabled",false).apply();stopService(new Intent(this,Assistant.class));Assistant.status="Выключен";});
