 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);applyVerificationWindow();} void applyVerificationWindow(){getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(getIntent().getBooleanExtra("verify_ui",false)){getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);new Handler().postDelayed(()->getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON),300000);}} void copy(String path,File out)throws Exception{String[] names=getAssets().list(path);if(names.length>0){out.mkdirs();for(String n:names)copy(path+"/"+n,new File(out,n));}else{out.getParentFile().mkdirs();try(InputStream in=getAssets().open(path);OutputStream os=new FileOutputStream(out)){byte[] b=new byte[65536];int k;while((k=in.read(b))>0)os.write(b,0,k);}}}
 void start(String action){start(action,null);}void start(String action,String q){if(!ready){Toast.makeText(this,"Подождите подготовку модели",0).show();return;}if(!action.equals("TEXT")&&checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){pendingListen=action.equals("LISTEN");requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},1);return;}Intent i=new Intent(this,Assistant.class).setAction(action);if(q!=null)i.putExtra("text",q);startForegroundService(i);}
